import React, { useState, useEffect } from 'react';
import { useAuth } from '../context/AuthContext';
import api from '../services/api';

const VILLES = ['Tunis', 'Sfax', 'Sousse', 'Monastir', 'Nabeul', 'Bizerte', 'Kairouan', 'Ariana'];

export default function Profile() {
  const { user } = useAuth();
  const [form, setForm] = useState({
    user_prenom: '', user_nom: '', email: '', ville: '', bio: '', telephone: '',
    tarifs_matieres: [], photo_url: null
  });
  const [structure, setStructure] = useState([]);
  const [loading, setLoading] = useState(true);
  const [saved, setSaved] = useState(false);

  useEffect(() => {
    fetchProfileData();
  }, [user]);

  const fetchProfileData = async () => {
    try {
      const res = await api.get('/api/professeurs/me');
      const d = res.data;
      // SECURITÉ : On s'assure que rien n'est null
      setForm({
        ...d,
        user_prenom: d.user_prenom || '',
        user_nom: d.user_nom || '',
        email: d.email || '',
        ville: d.ville || '',
        telephone: d.telephone || '',
        bio: d.bio || '',
        tarifs_matieres: d.tarifs_matieres || []
      });

      const resStruct = await api.get('/api/admin/referentiel/structure');
      setStructure(resStruct.data);
      setLoading(false);
    } catch (e) {
      console.error("Crash Profil :", e);
      setLoading(false);
    }
  };

  const handleInput = (key, val) => setForm(prev => ({ ...prev, [key]: val }));

  const handleToggle = (mId, nId) => {
    let list = [...(form.tarifs_matieres || [])];
    const exists = list.some(t => t.matiere_id === mId && t.niveau_id === nId);
    if (exists) list = list.filter(t => !(t.matiere_id === mId && t.niveau_id === nId));
    else list.push({ matiere_id: mId, niveau_id: nId, tarif: 20 });
    setForm({ ...form, tarifs_matieres: list });
  };

  const handleSave = async () => {
    try {
      await api.put('/api/professeurs/me', {
        nom: form.user_nom, prenom: form.user_prenom, ville: form.ville,
        telephone: form.telephone, bio: form.bio,
        tarifs_complets: form.tarifs_matieres 
      });
      setSaved(true); setTimeout(() => setSaved(false), 2000);
      alert("✅ Enregistré");
    } catch (e) { alert("Erreur"); }
  };

  const inp = { background: 'var(--surface2)', border: '1px solid var(--border)', borderRadius: 10, color: 'var(--text)', padding: '12px', width: '100%', outline: 'none', marginBottom: '10px' };

  if (loading) return <div style={{padding:50, textAlign:'center'}}>Chargement...</div>;

  return (
    <div style={{ padding: 32, maxWidth: 1200, margin: '0 auto' }}>
      <h2 style={{ fontFamily: 'Syne', marginBottom: 30 }}>⚙️ Paramètres du profil</h2>
      <div style={{ display: 'grid', gridTemplateColumns: '400px 1fr', gap: 30 }}>
        <div style={{ background: 'var(--card)', border: '1px solid var(--border)', borderRadius: 20, padding: 24 }}>
          <h3>👤 Mon Identité</h3>
          <label style={{fontSize:'.7rem'}}>Prénom</label>
          <input style={inp} value={form.user_prenom} onChange={e => handleInput('user_prenom', e.target.value)} />
          <label style={{fontSize:'.7rem'}}>Nom</label>
          <input style={inp} value={form.user_nom} onChange={e => handleInput('user_nom', e.target.value)} />
          <label style={{fontSize:'.7rem'}}>Email</label>
          <input style={{...inp, opacity:0.5}} value={form.email} readOnly />
          <label style={{fontSize:'.7rem'}}>Ville</label>
          <select style={inp} value={form.ville} onChange={e => handleInput('ville', e.target.value)}>
             {VILLES.map(v => <option key={v} value={v}>{v}</option>)}
          </select>
          <button onClick={handleSave} style={{ width:'100%', background:'var(--accent)', color:'#fff', padding:14, borderRadius:12, border:'none', fontWeight:600 }}>Sauvegarder</button>
        </div>

        <div style={{ background: 'var(--card)', border: '1px solid var(--border)', borderRadius: 20, padding: 24 }}>
          <h3>📚 Mes Enseignements</h3>
          {structure.map(dom => (
            <div key={dom.id} style={{marginBottom:20}}>
              <div style={{color:'var(--accent)', fontWeight:800, marginBottom:10}}>📂 {dom.nom}</div>
              {dom.niveaux?.map(niv => (
                <div key={niv.id} style={{marginLeft:15, marginBottom:10}}>
                   <div style={{fontWeight:600, fontSize:'.85rem'}}>🎓 {niv.nom}</div>
                   {niv.matieres?.map(mat => (
                     <div key={mat.id} style={{display:'flex', gap:10, alignItems:'center'}}>
                        <input type="checkbox" checked={form.tarifs_matieres.some(t=>t.matiere_id===mat.id && t.niveau_id===niv.id)} onChange={()=>handleToggle(mat.id, niv.id)} />
                        <span style={{fontSize:'.8rem'}}>{mat.nom}</span>
                     </div>
                   ))}
                </div>
              ))}
            </div>
          ))}
        </div>
      </div>
    </div>
  );
}
